// POST /api/generate — the AI ART GENERATOR (origination arc): vector icon
// marks and tile-cover artwork, generated by Claude from the wiki's own
// identity (name, tags, tagline, blurb, category colors) plus an optional
// designer hint. Returns sanitized SVG as a data URI that drops straight into
// the existing `art` slots (tile_cover.src / icon.src) — no storage needed.
//
// Security: the Anthropic key lives ONLY in this server route (Vercel env
// ANTHROPIC_API_KEY — never shipped to the browser). Callers must present a
// signed-in Supabase session whose role is admin or contributor (checked via
// the security-definer my_role() with the caller's own JWT). Output is
// sanitized server-side and rendered only via <img>/CSS background.
import Anthropic from '@anthropic-ai/sdk';
import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { buildSvgPrompt, GEN_SYSTEM, extractSvg, sanitizeSvg, svgToDataUri } from '../../../lib/svg-gen.mjs';

export const maxDuration = 60;   // vector covers can take a while to draw

const MODEL = process.env.ANTHROPIC_MODEL || 'claude-opus-5-5';

export async function POST(req: Request) {
  if (!process.env.ANTHROPIC_API_KEY) {
    return NextResponse.json({ error: 'AI generation is not configured — set ANTHROPIC_API_KEY in Vercel (see docs/supabase-setup.md)' }, { status: 503 });
  }
  let body: any;
  try { body = await req.json(); } catch { return NextResponse.json({ error: 'bad request' }, { status: 400 }); }
  const kind = body?.kind === 'icon' ? 'icon' : body?.kind === 'cover' ? 'cover' : null;
  const w = body?.wiki;
  if (!kind || !w?.name) return NextResponse.json({ error: 'kind (icon|cover) and wiki.name are required' }, { status: 400 });

  // ── caller must be a signed-in admin/contributor (their JWT, our check) ──
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL, anon = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  const token = (req.headers.get('authorization') || '').replace(/^Bearer\s+/i, '');
  if (!url || !anon || !token) return NextResponse.json({ error: 'sign in to generate art' }, { status: 401 });
  const asCaller = createClient(url, anon, { global: { headers: { Authorization: `Bearer ${token}` } }, auth: { persistSession: false } });
  const role = await asCaller.rpc('my_role');
  if (role.error || !['admin', 'contributor'].includes(role.data)) {
    return NextResponse.json({ error: 'generation is for contributor accounts' }, { status: 403 });
  }

  const prompt = buildSvgPrompt(kind, {
    name: String(w.name).slice(0, 120),
    genreLabel: w.genreLabel ? String(w.genreLabel).slice(0, 60) : null,
    tagline: w.tagline ? String(w.tagline).slice(0, 160) : null,
    blurb: w.blurb ? String(w.blurb).slice(0, 400) : null,
    colors: Array.isArray(w.colors) ? w.colors.slice(0, 6).map((c: any) => String(c).slice(0, 48)) : [],
  }, body?.hint ? String(body.hint).slice(0, 400) : null);

  try {
    const client = new Anthropic();
    const res = await client.messages.create({
      model: MODEL,
      max_tokens: 16000,
      system: GEN_SYSTEM,
      messages: [{ role: 'user', content: prompt }],
    });
    if (res.stop_reason === 'refusal') {
      return NextResponse.json({ error: 'the model declined this request — try a different hint' }, { status: 422 });
    }
    const text = res.content.filter((b) => b.type === 'text').map((b: any) => b.text).join('\n');
    const svg = extractSvg(text);
    if (!svg) return NextResponse.json({ error: 'no SVG in the response — try again' }, { status: 502 });
    const clean = sanitizeSvg(svg);
    return NextResponse.json({ svg: clean, dataUri: svgToDataUri(clean) });
  } catch (e: any) {
    const msg = e?.message || String(e);
    return NextResponse.json({ error: `generation failed: ${msg}` }, { status: 502 });
  }
}
